using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Eval;

/// <summary>
/// Shared setup for evaluation scenarios: configures the chat client,
/// evaluators, and the reporting storage used across all eval modes.
/// </summary>
internal static class EvalSetup
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT");

    private static readonly string DeploymentName =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var client = new AzureOpenAIClient(new Uri(Endpoint), new DefaultAzureCredential());
        return client.GetChatClient(DeploymentName).AsIChatClient();
    }

    public static IList<IEvaluator> GetQualityEvaluators()
    {
        return
        [
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
            new CompletenessEvaluator(),
        ];
    }

    public static ReportingConfiguration CreateReportingConfiguration(
        string scenarioName,
        IList<IEvaluator>? evaluators = null)
    {
        var storage = new DiskBasedReportingStorage(
            storageRootPath: Path.Combine(
                Directory.GetCurrentDirectory(), ".eval-results"));

        return new ReportingConfiguration(
            evaluators: evaluators ?? [],
            reportingStorage: storage,
            scenarioName: scenarioName);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: validates that the chat client produces responses and
/// records token usage and latency without judging answer quality.
/// </summary>
[TestClass]
public class TelemetryEvalTests
{
    private static ReportingConfiguration s_config = null!;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfiguration("Telemetry");
    }

    [TestMethod]
    public async Task Chat_ProducesResponse_WithTokenMetrics()
    {
        await using var scenario = await s_config.CreateScenarioRunAsync();

        var client = EvalSetup.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await client.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);

        scenario.Record(
            new TurnResult(
                request: messages,
                response: response));
    }

    [TestMethod]
    public async Task Chat_StreamProducesTokens()
    {
        await using var scenario = await s_config.CreateScenarioRunAsync();

        var client = EvalSetup.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain recursion in one sentence.")
        };

        var tokens = new List<string>();
        await foreach (var update in client.GetStreamingResponseAsync(messages))
        {
            if (update.Text is not null)
                tokens.Add(update.Text);
        }

        Assert.IsTrue(tokens.Count > 0, "Streaming should produce at least one token.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: evaluates response quality using relevance, coherence,
/// fluency, groundedness, and completeness evaluators.
/// </summary>
[TestClass]
public class QualityEvalTests
{
    private static ReportingConfiguration s_config = null!;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfiguration(
            "Quality",
            EvalSetup.GetQualityEvaluators());
    }

    [TestMethod]
    public async Task Answer_MeetsQualityBar()
    {
        await using var scenario = await s_config.CreateScenarioRunAsync();

        var client = EvalSetup.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers questions accurately."),
            new(ChatRole.User, "What are the three states of matter?")
        };

        var response = await client.GetResponseAsync(messages);

        var result = scenario.Record(
            new TurnResult(
                request: messages,
                response: response));

        await scenario.EvaluateAsync(result);

        foreach (var metric in result.Metrics)
        {
            if (metric.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 3,
                    $"Metric '{metric.Key}' scored {numericValue.Value}, expected >= 3.");
            }
        }
    }

    [TestMethod]
    public async Task GroundedAnswer_ScoresHighOnGroundedness()
    {
        await using var scenario = await s_config.CreateScenarioRunAsync();

        var client = EvalSetup.CreateChatClient();

        var context = "The Eiffel Tower is located in Paris, France. It was built in 1889.";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"Answer based only on this context: {context}"),
            new(ChatRole.User, "Where is the Eiffel Tower and when was it built?")
        };

        var response = await client.GetResponseAsync(messages);

        var result = scenario.Record(
            new TurnResult(
                request: messages,
                response: response));

        await scenario.EvaluateAsync(result);

        foreach (var metric in result.Metrics)
        {
            if (metric.Key.Contains("Groundedness") &&
                metric.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 4,
                    $"Groundedness scored {numericValue.Value}, expected >= 4.");
            }
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Compare mode: runs the same prompts against two model configurations
/// (or system prompts) and compares their quality scores side-by-side.
/// Results are stored with distinct scenario names for diffing in reports.
/// </summary>
[TestClass]
public class CompareEvalTests
{
    private static ReportingConfiguration s_configA = null!;
    private static ReportingConfiguration s_configB = null!;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        var evaluators = EvalSetup.GetQualityEvaluators();
        s_configA = EvalSetup.CreateReportingConfiguration("Compare_VariantA", evaluators);
        s_configB = EvalSetup.CreateReportingConfiguration("Compare_VariantB", evaluators);
    }

    [TestMethod]
    public async Task CompareSystemPrompts_QualityDelta()
    {
        var client = EvalSetup.CreateChatClient();

        var userMessage = new ChatMessage(ChatRole.User, "Summarize the benefits of unit testing.");

        // Variant A: terse system prompt
        var messagesA = new List<ChatMessage>
        {
            new(ChatRole.System, "Be concise."),
            userMessage
        };

        // Variant B: detailed system prompt
        var messagesB = new List<ChatMessage>
        {
            new(ChatRole.System, "You are an expert software engineer. Provide thorough, well-structured answers with examples."),
            userMessage
        };

        await using var scenarioA = await s_configA.CreateScenarioRunAsync();
        var responseA = await client.GetResponseAsync(messagesA);
        var resultA = scenarioA.Record(new TurnResult(request: messagesA, response: responseA));
        await scenarioA.EvaluateAsync(resultA);

        await using var scenarioB = await s_configB.CreateScenarioRunAsync();
        var responseB = await client.GetResponseAsync(messagesB);
        var resultB = scenarioB.Record(new TurnResult(request: messagesB, response: responseB));
        await scenarioB.EvaluateAsync(resultB);

        // Both variants should meet a minimum bar; the report shows the delta.
        AssertMinimumBar(resultA, "Variant A");
        AssertMinimumBar(resultB, "Variant B");
    }

    private static void AssertMinimumBar(TurnResult result, string label)
    {
        foreach (var metric in result.Metrics)
        {
            if (metric.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 2,
                    $"[{label}] Metric '{metric.Key}' scored {numericValue.Value}, expected >= 2.");
            }
        }
    }
}

