+using Microsoft.Extensions.AI;
+using Microsoft.Extensions.AI.Evaluation;
+using Microsoft.Extensions.AI.Evaluation.Quality;
+using Microsoft.Extensions.AI.Evaluation.Reporting;
+using Microsoft.VisualStudio.TestTools.UnitTesting;
+
+namespace MyApp.Eval;
+
+/// <summary>
+/// Compare mode: runs the same prompts against two model configurations
+/// (or system prompts) and compares their quality scores side-by-side.
+/// Results are stored with distinct scenario names for diffing in reports.
+/// </summary>
+[TestClass]
+public class CompareEvalTests
+{
+    private static ReportingConfiguration s_configA = null!;
+    private static ReportingConfiguration s_configB = null!;
+
+    [ClassInitialize]
+    public static void Init(TestContext _)
+    {
+        var evaluators = EvalSetup.GetQualityEvaluators();
+        s_configA = EvalSetup.CreateReportingConfiguration("Compare_VariantA", evaluators);
+        s_configB = EvalSetup.CreateReportingConfiguration("Compare_VariantB", evaluators);
+    }
+
+    [TestMethod]
+    public async Task CompareSystemPrompts_QualityDelta()
+    {
+        var client = EvalSetup.CreateChatClient();
+
+        var userMessage = new ChatMessage(ChatRole.User, "Summarize the benefits of unit testing.");
+
+        // Variant A: terse system prompt
+        var messagesA = new List<ChatMessage>
+        {
+            new(ChatRole.System, "Be concise."),
+            userMessage
+        };
+
+        // Variant B: detailed system prompt
+        var messagesB = new List<ChatMessage>
+        {
+            new(ChatRole.System, "You are an expert software engineer. Provide thorough, well-structured answers with examples."),
+            userMessage
+        };
+
+        await using var scenarioA = await s_configA.CreateScenarioRunAsync();
+        var responseA = await client.GetResponseAsync(messagesA);
+        var resultA = scenarioA.Record(new TurnResult(request: messagesA, response: responseA));
+        await scenarioA.EvaluateAsync(resultA);
+
+        await using var scenarioB = await s_configB.CreateScenarioRunAsync();
+        var responseB = await client.GetResponseAsync(messagesB);
+        var resultB = scenarioB.Record(new TurnResult(request: messagesB, response: responseB));
+        await scenarioB.EvaluateAsync(resultB);
+
+        // Both variants should meet a minimum bar; the report shows the delta.
+        AssertMinimumBar(resultA, "Variant A");
+        AssertMinimumBar(resultB, "Variant B");
+    }
+
+    private static void AssertMinimumBar(TurnResult result, string label)
+    {
+        foreach (var metric in result.Metrics)
+        {
+            if (metric.Value is NumericMetricValue numericValue)
+            {
+                Assert.IsTrue(
+                    numericValue.Value >= 2,
+                    $"[{label}] Metric '{metric.Key}' scored {numericValue.Value}, expected >= 2.");
+            }
+        }
+    }
+}
+

